	metrics (
		PROJECT_TVP.TOTAL_PROJECT_INDICATION_RECORDS as COUNT(indication_unique_code, project_code) comment='Counts the total number of project-indication records in the Target Value Proposition data, including duplicates. Use when questions ask about ''total number of records'', ''how many TVP entries'', ''total count of project-indication records'', or ''volume of TVP data''. Helps measure the total volume of TVP data available, track data completeness across projects and indications, and understand the overall size of the TVP dataset for reporting and analysis purposes.',
		PROJECT_TVP.UNIQUE_PROJECT_INDICATION_COMBINATIONS as COUNT(DISTINCT HASH(indication_unique_code, project_code)) comment='Counts the number of distinct project-indication combinations in the Target Value Proposition data. Use when questions ask about ''how many unique project-indication pairs'', ''number of distinct combinations'', ''total unique TVP records'', or ''count of different project-indication relationships''. Helps measure the scope of TVP coverage across the portfolio, track the number of unique value propositions being developed, and assess the breadth of indication coverage per project.'
	)
