-9df1-d3429e09d54e) */","question":"What are the different project phases available in the project indication data?","verified_at":1771155368,"verified_by":"ADAM","use_as_onboarding_question":false},{"name":"\\"HOW MANY PROJECTS HAVE READOUT MILESTONES PLANNED FOR THIS YEAR?\\"","sql":"SELECT\\n  COUNT(DISTINCT project_code) AS projects_with_readouts\\nFROM\\n  vw_project_indication_readouts_milestones\\nWHERE\\n  DATE_PART(''YEAR'', readout_planned_dt) = DATE_PART(''YEAR'', CURRENT_DATE)\\n  /* Generated by Cortex Analyst (request_id: fb254091-eb5f-4c64-ba4d-722d88548ccf) */","question":"How many projects have readout milestones planned for this year?","verified_at":1771155351,"verified_by":"ADAM","use_as_onboarding_question":false},{"name":"\\"What is the overall data coverage and uniqueness summary for medical indications and projects in our portfolio?\\"","sql":"SELECT\\n  COUNT(indication_code_meddra) AS count_indication_code_meddra,\\n  COUNT(DISTINCT indication_code_meddra) AS distinct_indication_code_meddra,\\n  COUNT(project_code) AS count_project_code,\\n  COUNT(DISTINCT project_code) AS distinct_project_code,\\n  COUNT(indication_unique_code, project_code) AS count_indication_unique_code_project_code,\\n  COUNT(\\n    DISTINCT HASH(indication_unique_code, project_code)\\n  ) AS distinct_indication_unique_code_project_code\\nFROM\\n  PROJECT_INDICATION_FLAT","question":"What is the overall data coverage and uniqueness summary for medical indications and projects in our portfolio?","verified_at":1771155586,"verified_by":"ADAM","use_as_onboarding_question":false},{"name":"\\"How many project-indication combinations exist in our TVP portfolio and how many unique combinations are there?\\"","sql":"SELECT\\n  COUNT(indication_unique_code, project_code) AS count_indication_unique_code_project_code,\\n  COUNT(\\n    DISTINCT HASH(indication_unique_code, project_code)\\n  ) AS distinct_indication_unique_code_project_code\\nFROM\\n  vw_project_tvp","question":"How many project-indication combinations exist in our TVP portfolio and how many unique combinations are there?","verified_at":1771155602,"verified_by":"ADAM","use_as_onboarding_question":false},{"name":"\\"How many project-indication combinations exist in our portfolio and how many of those are unique?\\"","sql":"SELECT\\n  COUNT(indication_unique_code, project_code) AS count_indication_unique_code_project_code,\\n  COUNT(\\n    DISTINCT HASH(indication_unique_code, project_code)\\n  ) AS distinct_indication_unique_code_project_code\\nFROM\\n  vw_project_indication_tpp","question":"How many project-indication combinations exist in our portfolio and how many of those are unique?","verified_at":1771155621,"verified_by":"ADAM","use_as_onboarding_question":false}]}')